function handleSwipe(x,y,dist){if(state!=='play'||dist<45)return;let found=false;for(let e of entities)if(e.type==='wind'&&!e.hit&&Math.abs(e.y-y)<90&&Math.abs(e.x-x)<125){e.hit=true;effect(e.x,e.y,'#b9f8ff',14);score+=30;found=true}if(found){combo++;perfectBlocks++;onDefense();if(perfectBlocks%4===0)energy=Math.min(4,energy+1);comboTimer=6;face='determined';faceT=.5;playNote(700,'triangle',.1);notify(TXT().toastWind);updateHud()}}
