 if(heroFlashT>0){const hero=AVATARS[settings.avatar]||AVATARS[0];ctx.save();ctx.globalAlpha=Math.min(.6,heroFlashT*.45);ctx.fillStyle=hero.accent;for(let i=0;i<10;i++){let th=i*Math.PI*2/10+t*1.5;ctx.beginPath();ctx.arc(HEAD.x+Math.cos(th)*HEAD.r*1.7,HEAD.y+HEAD.r*.7+Math.sin(th)*HEAD.r*1.5,4+5*Math.abs(Math.sin(t*8+i)),0,Math.PI*2);ctx.fill()}ctx.restore()}
