function drawTutorial(){if(save.tutDone||state!=='play')return;const e=entities.find(e=>!e.hit);if(!e)return;const pulse=(Math.sin(t*8)+1)/2;ctx.save();ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.globalAlpha=.9;ctx.beginPath();ctx.arc(e.x,e.y,e.size+18+pulse*10,0,Math.PI*2);ctx.stroke();let fx=e.x+18,fy=e.y+26+pulse*8;if(e.type==='wind'){fx=e.x+((t*160)%120)-30;fy=e.y+34}ctx.font='42px system-ui';ctx.textAlign='left';ctx.globalAlpha=1;ctx.fillText('👆',fx,fy+30);ctx.font='900 18px system-ui';ctx.textAlign='center';ctx.lineWidth=5;ctx.strokeStyle='#3c2656';ctx.fillStyle='#fff';const msg=e.type==='wind'?L3('옆으로 쓱 밀어요!','向旁边划一下！','Swipe it away!'):L3('터치!','点它！','Tap!');const my=Math.max(118,e.y-e.size-26);ctx.strokeText(msg,clamp(e.x,70,W-70),my);ctx.fillText(msg,clamp(e.x,70,W-70),my);ctx.restore()}
