function drawEntity(e){ctx.save();ctx.translate(e.x,e.y);const img=IMGS[e.type];if(img&&img.complete&&img.naturalWidth){if(e.type==='bird'){ctx.rotate(Math.sin(t*4)*.12);let s=e.size*3.1;if(e.boss){ctx.shadowColor='#f8b937';ctx.shadowBlur=25}ctx.drawImage(img,-s*.6,-s*.58,s*1.25,s*1.1);ctx.shadowBlur=0;if(e.boss){ctx.fillStyle='#ffe68b';ctx.strokeStyle='#45304f';ctx.lineWidth=3;ctx.font='bold 22px system-ui';ctx.textAlign='center';ctx.strokeText('👑 '+e.hp,e.size*.06,-e.size*2.0);ctx.fillText('👑 '+e.hp,e.size*.06,-e.size*2.0)}}else if(e.type==='paper'){ctx.rotate(e.rot+Math.sin(t*4)*.12);let s=e.size*3.0;ctx.drawImage(img,-s*.6,-s*.65,s*1.25,s*1.25)}else if(e.type==='wind'){ctx.rotate(Math.sin(t*5)*.08);let s=e.size*3.0;ctx.drawImage(img,-s*.6,-s*.65,s*1.35,s*1.35)}else if(e.type==='runner'){ctx.rotate(Math.sin(t*15)*.12);let s=e.size*2.8;ctx.drawImage(img,-s*.62,-s*.62,s*1.25,s*1.0)}ctx.restore();return}if(e.type==='bird'){let flap=Math.sin(t*20+e.wing)*12;ctx.rotate(Math.sin(t*4)*.15);ell(0,0,28,21,'#4d4b65','#24273a',3);ell(19,-12,17,17,'#50506b','#24273a',3);ell(24,-14,4,5,'white',null);ell(26,-13,2,2,'#17151d',null);path([[32,-7],[47,-1],[32,4]],'#ee9c32',6);ctx.save();ctx.rotate(flap*.03);ell(-10,-14,15,9,'#85869e','#26273e',2);ctx.restore();path([[-15,15],[-22,25]],'#e89633',3)}else if(e.type==='paper'){ctx.rotate(e.rot+Math.sin(t*4)*.17);rrect(-23,-30,46,60,3,'#fffdfa','#54496c',3);for(let i=-13;i<=16;i+=10)path([[-14,i],[14,i]],'#ba8e9e',2);ctx.font='bold 23px sans-serif';ctx.textAlign='center';ctx.fillStyle='#b64461';ctx.fillText('!',0,6)}else if(e.type==='wind'){ctx.strokeStyle='#ffffff';ctx.lineWidth=8;ctx.lineCap='round';for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(-30,i*16);ctx.bezierCurveTo(0,i*16-20,20,i*16+20,42,i*16-2);ctx.stroke();ctx.lineWidth=3;ctx.strokeStyle='#65b9e2'}}else{ctx.rotate(Math.sin(t*15)*.3);path([[-4,-8],[-15,16]],'#3c2934',4);path([[4,-8],[15,16]],'#3c2934',4);path([[-3,-12],[-13,-31],[8,-46],[13,-29],[3,-13]],'#3a252d',5);ell(0,-4,13,15,'#573735','#2f2028',2);ell(-4,-6,3,4,'#fff',null);ell(5,-6,3,4,'#fff',null)}ctx.restore()}
function draw(){ctx.clearRect(0,0,W,H);syncHairs(-1);drawScene();if(state==='play'||state==='quiz'||state==='pause'||state==='result'){for(let e of entities)if(!e.hit)drawEntity(e)}for(let p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ell(p.x,p.y,p.r,p.r,p.c,null)}ctx.globalAlpha=1;if(state==='play'&&shield+xShield>0){ctx.save();ctx.font='bold 18px system-ui';ctx.textAlign='center';ctx.fillStyle='#186e81';ctx.strokeStyle='#ffffff';ctx.lineWidth=4;ctx.strokeText('🛡️ '+(shield+xShield),W*.5,H*.14);ctx.fillText('🛡️ '+(shield+xShield),W*.5,H*.14);ctx.restore()}if(state==='play'&&combo>=3){ctx.save();ctx.textAlign='center';ctx.font='900 24px system-ui';ctx.lineWidth=5;ctx.strokeStyle='#3c2656';ctx.fillStyle='#ffe866';ctx.strokeText('COMBO x'+combo,W*.5,H*.19);ctx.fillText('COMBO x'+combo,W*.5,H*.19);ctx.restore()}drawPullFx();drawPopTexts();drawBubble();drawTutorial();if(state==='play'&&hairs<=2){ctx.save();ctx.globalAlpha=.35+.25*Math.sin(t*9);ctx.strokeStyle='#fa6c63';ctx.lineWidth=12;ctx.strokeRect(5,5,W-10,H-10);ctx.restore()}}
function end(win){if(state!=='play')return;hideReaction();state='result';track(win?'game_win':'game_fail',{hairs,score,level:settings.age});entities=[];const ranks=[{min:7,ko:'모발의 왕',zh:'发量王者',en:'King of Hair',emoji:'👑'},{min:5,ko:'헤어라인 수호자',zh:'发际线守护者',en:'Hairline Guardian',emoji:'😎'},{min:3,ko:'정수리의 용사',zh:'地中海勇士',en:'Crown Warrior',emoji:'😤'},{min:1,ko:'마지막 가닥의 반항',zh:'最后的倔强',en:'Last Strand Rebel',emoji:'🥹'},{min:0,ko:'빛나는 전설',zh:'光头传奇',en:'Bald Legend',emoji:'👨🏻‍🦲'}];let r=ranks.find(r=>hairs>=r.min),best=0;try{let key='hairDefenseBest_'+settings.age;best=Math.max(score,Number(localStorage.getItem(key)||0));localStorage.setItem(key,best)}catch(e){best=score}tr('resultTop',win?TXT().win:TXT().lose);tr('resultEmoji',r.emoji);tr('ranking',r[settings.ui]);tr('rankingZh',r.zh);tr('resultStats',TXT().stats(hairs,score,correct));tr('recordText',TXT().record(best));tr('resultTip',(AVATARS[settings.avatar].name[settings.ui==='zh'?1:settings.ui==='en'?2:0])+' · '+TXT().tip);progress.runs++;progress.totalBlocks+=roundBlocks;progress.totalWords+=correct;progress.wins+=win?1:0;progress.heroes[settings.avatar]++;saveProgress();payRun(win);let n=progress.heroes[settings.avatar];let level=heroLevel(n);tr('resultAchievement',settings.ui==='zh'?('🏆 防守 '+roundBlocks+' 次 · 词语 '+correct+' 个'):settings.ui==='en'?('🏆 '+roundBlocks+' defenses · '+correct+' words'):('🏆 방어 '+roundBlocks+'회 · 학습 정답 '+correct+'개'));tr('resultProgress',(settings.ui==='zh'?'🎖️ 英雄熟练度':settings.ui==='en'?'🎖️ Hero mastery':'🎖️ 캐릭터 숙련도')+' Lv.'+level+' · '+n+(settings.ui==='zh'?' 局':settings.ui==='en'?' rounds':'판')+' | '+progressText());renderAvatars();setResultHero();renderResultMoney();screen('result');playNote(win?880:210,'triangle',.28)}
function pause(){if(state!=='play')return;stopSpeech();state='pause';screen('pause')}function resume(){if(state==='pause'){state='play';screen('')}}function touchXY(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}canvas.addEventListener('pointerdown',e=>{if(state!=='play')return;const p=touchXY(e);pointers.set(e.pointerId,{x:p.x,y:p.y,ox:p.x,oy:p.y,max:0});canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{const p=pointers.get(e.pointerId);if(!p)return;const xy=touchXY(e);p.max=Math.max(p.max,Math.hypot(xy.x-p.ox,xy.y-p.oy));p.x=xy.x;p.y=xy.y});canvas.addEventListener('pointerup',e=>{const p=pointers.get(e.pointerId);if(!p)return;pointers.delete(e.pointerId);if(p.max>43)handleSwipe(p.x,p.y,p.max);else handleTap(p.x,p.y)});canvas.addEventListener('pointercancel',e=>pointers.delete(e.pointerId));window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state==='play')pause();else if(state==='pause')resume();else if(state==='quiz'){$('skipQuiz').click()}}if(e.key===' '&&state==='play'){e.preventDefault();quiz()}});
/* ===== v9 수익화 계층: 광고 · 코인 · 매일 보상 · 공유 · 통계 ===== */
/* ★ 광고 단위 ID 넣는 곳: 플랫폼 관리자 화면에서 받은 '보상형 영상' ID를 따옴표 안에 넣으세요. 비어 있으면 2초짜리 테스트 광고가 나옵니다. */
const AD_UNIT={wx:'',tt:''};
const API=(typeof wx!=='undefined'&&wx&&wx.createRewardedVideoAd)?wx:(typeof tt!=='undefined'&&tt&&tt.createRewardedVideoAd)?tt:null;
const PLAT=!API?'web':(typeof tt!=='undefined'&&API===tt)?'tt':'wx';
const HERO_PRICE=[0,0,400,900],BOOST_COST=50,BOX_COINS=60,BOX_MAX=3,REVIVE_HAIRS=2;
const CHECKIN=[30,40,50,60,80,100,200];
const MISSIONS=[{k:'runs',n:3,c:40,t:['게임 3판 하기','玩 3 局','Play 3 rounds']},{k:'correct',n:5,c:50,t:['단어 5개 맞히기','答对 5 题','Get 5 answers right']},{k:'blocks',n:40,c:60,t:['공격 40번 막기','防守 40 次','Block 40 attacks']}];
const SAVE_KEY='hairDefenseSaveV9';
const L3=(ko,zh,en)=>settings.ui==='zh'?zh:settings.ui==='en'?en:ko;
function today(){const d=new Date();return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()}
function newDaily(){return{date:today(),runs:0,correct:0,blocks:0,claimed:[0,0,0],box:0,hint:0}}
function loadSave(){const s={coins:0,unlocked:[1,1,0,0],ui:'',age:1,study:'mix',sound:true,music:true,vib:true,tutDone:0,voice:true,boost:false,daily:newDaily(),checkin:{last:'',day:0},best:[0,0,0,0,0,0],stats:{ads:0,runs:0}};try{const v=JSON.parse(localStorage.getItem(SAVE_KEY)||'{}')||{};for(const k in s){if(v[k]===undefined||v[k]===null)continue;if(Array.isArray(s[k])){if(Array.isArray(v[k]))s[k]=s[k].map((d,i)=>v[k][i]===undefined?d:v[k][i])}else if(typeof s[k]==='object')Object.assign(s[k],v[k]);else if(typeof v[k]===typeof s[k])s[k]=v[k]}}catch(e){}s.coins=Math.max(0,Math.floor(Number(s.coins)||0));s.unlocked[0]=1;s.unlocked[1]=1;if(!Array.isArray(s.daily.claimed))s.daily.claimed=[0,0,0];s.age=clamp(Math.floor(Number(s.age)||0),0,5);if(!['mix','zh','ko','en'].includes(s.study))s.study='mix';return s}
const save=loadSave();
function persist(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(save))}catch(e){}}
function dailyInit(){if(save.daily.date!==today()){save.daily=newDaily();persist()}}
const EVENTS=[];
function track(name,data){data=data||{};try{if(PLAT==='wx'&&API.reportEvent)API.reportEvent(name,data);else if(PLAT==='tt'&&API.reportAnalytics)API.reportAnalytics(name,data)}catch(e){}EVENTS.push([name,data]);if(EVENTS.length>300)EVENTS.shift()}
function detectLang(){try{const q=new URLSearchParams(location.search).get('lang');if(q&&LANG[q])return q}catch(e){}if(save.ui&&LANG[save.ui])return save.ui;let n=(navigator.language||'').toLowerCase(),tz='';try{tz=Intl.DateTimeFormat().resolvedOptions().timeZone||''}catch(e){}if(n.startsWith('zh')||/Shanghai|Chongqing|Urumqi|Harbin|Hong_Kong|Macau|Taipei/.test(tz))return'zh';if(n.startsWith('ko'))return'ko';return'en'}
function isMenu(name){return ['start','reward','privacy','settings','loading'].includes(name)}
let revived=false,xShield=0,lastCoins=0,doubled=false,adBusy=false,adTimer=0;
function addCoins(n){save.coins+=n;persist();tr('coinCount',save.coins);tr('coinCount2',save.coins)}

/* ---- 보상형 광고: 보고 싶을 때만, 끝까지 봐야 보상 ---- */
function showAd(place,onReward){if(adBusy)return;adBusy=true;wantMusic();track('ad_open',{place});
 const done=ok=>{adBusy=false;wantMusic();if(ok){save.stats.ads++;persist();track('ad_reward',{place});onReward()}else{track('ad_fail',{place,why:'skip'});notify(L3('광고를 끝까지 봐야 보상을 받아요','看完广告才能领取奖励','Watch the full ad to get the reward'),1.8)}};
 const loadFail=()=>{adBusy=false;wantMusic();track('ad_fail',{place,why:'load'});notify(L3('광고를 불러오지 못했어요. 잠시 후 다시 시도해 주세요','广告加载失败，请稍后再试','Ad failed to load. Please try again later'),2)};
 const unit=AD_UNIT[PLAT];
 if(API&&unit){try{const ad=API.createRewardedVideoAd({adUnitId:unit});const onClose=r=>{try{ad.offClose&&ad.offClose(onClose)}catch(e){}done(!r||r.isEnded!==false)};ad.onClose(onClose);ad.onError&&ad.onError(()=>{});ad.load().then(()=>ad.show()).catch(loadFail)}catch(e){loadFail()}return}
 let left=2;const layer=$('adLayer');tr('adTitle',L3('테스트 광고','测试广告','Test ad'));tr('adNote',L3('실제 출시판에서는 여기에 보상형 영상 광고가 나옵니다','正式版将在此播放激励视频广告','A rewarded video plays here in the live build'));tr('adCount',left);layer.classList.remove('hidden');
 clearInterval(adTimer);adTimer=setInterval(()=>{left--;tr('adCount',Math.max(0,left));if(left<=0){clearInterval(adTimer);layer.classList.add('hidden');done(true)}},1000)}

/* ---- 판 시작 / 부활 / 판 종료 보상 ---- */
function beginRun(){revived=false;xShield=0;doubled=false;lastCoins=0;dailyInit();save.age=settings.age;save.study=settings.study;if(save.boost){if(save.coins>=BOOST_COST){save.coins-=BOOST_COST;xShield=2;track('boost_use',{})}else save.boost=false}save.stats.runs++;persist();track('game_start',{level:settings.age,study:settings.study,hero:settings.avatar,boost:xShield?1:0})}
function offerRevive(){state='revive';stopSpeech();hideReaction();tr('reviveTitle',L3('마지막 한 가닥을 되살릴까요?','要救回最后的头发吗？','Bring your hair back?'));tr('reviveSub',L3('광고를 보면 머리카락 2가닥으로 이어서 해요 (한 판에 1번)','看广告可带着 2 根头发继续（每局 1 次）','Watch an ad to continue with 2 hairs (once per round)'));tr('reviveAdBtn',L3('📺 광고 보고 부활 +2','📺 看广告复活 +2','📺 Watch ad · Revive +2'));tr('reviveSkipBtn',L3('그냥 결과 보기','直接看结果','No thanks'));screen('revive');track('revive_offer',{time:Math.ceil(time)})}
function doRevive(){if(state!=='revive')return;revived=true;hairs=REVIVE_HAIRS;shield=Math.max(shield,1);lossGrace=3;entities=[];spawnTimer=2.5;face='happy';faceT=1.6;state='play';screen('');updateHud();effect(W*.5,H*.27,'#9df575',26);notify('💈 +'+REVIVE_HAIRS+'!',1.5);playNote(890,'sine',.25);track('revive_done',{})}
function payRun(win){dailyInit();lastCoins=Math.max(5,Math.round((score/60+hairs*3+(win?10:0))*LV[settings.age].coin));if(win){save.best[settings.age]=Math.max(save.best[settings.age]||0,hairs)}doubled=false;save.coins+=lastCoins;save.daily.runs++;save.daily.correct+=correct;save.daily.blocks+=roundBlocks;persist()}
function renderResultMoney(){if(state==='result'&&hairs>0&&$('resultTop').textContent===TXT().win)tr('recordText',$('recordText').textContent.split('  ')[0]+'  '+stars(hairs));tr('coinGain','🪙 +'+(doubled?lastCoins*2:lastCoins)+(doubled?' ✨':''));const d=$('doubleBtn');d.classList.toggle('hidden',doubled||lastCoins<=0);tr('doubleBtn',L3('📺 광고 보고 코인 2배','📺 看广告金币翻倍','📺 Watch ad · Double coins'));tr('shareBtn',L3('📤 친구에게 자랑하기','📤 分享给朋友','📤 Share'));tr('coinCount',save.coins)}
function shareGame(){track('share',{hairs,score});const text=L3('머리카락 '+hairs+'가닥으로 살아남았다! 너는 몇 가닥?','我守住了 '+hairs+' 根头发！你能守住几根？','I survived with '+hairs+' hairs. Can you beat that?');try{if(API&&API.shareAppMessage){API.shareAppMessage({title:text});return}if(navigator.share){navigator.share({title:document.title,text,url:location.href}).catch(()=>{});return}if(navigator.clipboard){navigator.clipboard.writeText(text+' '+location.href).then(()=>notify(L3('복사했어요! 붙여넣어 보내세요','已复制，粘贴发送吧','Copied! Paste to share'),1.6)).catch(()=>{})}}catch(e){}}

/* ---- 퀴즈 힌트: 하루 1번 무료, 그다음은 광고 ---- */
function setupHint(){dailyInit();const b=$('hintBtn');b.classList.remove('hidden');b.disabled=false;tr('hintBtn',save.daily.hint<1?L3('💡 힌트 (오늘 무료 1회)','💡 提示（今日免费 1 次）','💡 Hint (1 free today)'):L3('💡 힌트 📺','💡 提示 📺','💡 Hint 📺'))}
function applyHint(){if(state!=='quiz'||quizLocked)return;const wrong=Array.from($('quizOptions').children).filter(b=>b.textContent!==quizAnswer&&!b.disabled).sort(()=>Math.random()-.5).slice(0,Math.max(1,$('quizOptions').children.length-2));wrong.forEach(b=>{b.disabled=true;b.style.opacity='.3'});$('hintBtn').classList.add('hidden');track('hint_use',{})}
function useHint(){if(state!=='quiz'||quizLocked)return;if(save.daily.hint<1){save.daily.hint++;persist();applyHint()}else showAd('hint',applyHint)}

/* ---- 주인공 잠금 해제 / 시작 보호막 ---- */
function buyHero(i){viewHero=i;const price=HERO_PRICE[i];if(save.coins<price){notify(L3('🪙 '+(price-save.coins)+' 더 모으면 열려요!','还差 🪙'+(price-save.coins)+' 就能解锁！','🪙 '+(price-save.coins)+' more to unlock!'),1.8);return}save.coins-=price;save.unlocked[i]=1;settings.avatar=i;persist();try{localStorage.setItem('hairDefenseAvatar',String(i))}catch(e){}track('hero_unlock',{hero:i});viewHero=i;notify(L3('🎉 새 주인공 등장!','🎉 新主角解锁！','🎉 New hero unlocked!'),1.6);playNote(880,'triangle',.2);applyUI()}
function toggleBoost(){if(!save.boost&&save.coins<BOOST_COST){notify(L3('🪙 코인이 부족해요. 매일 보상에서 모아 보세요!','🪙 金币不足，去每日奖励领取吧！','🪙 Not enough coins. Check daily rewards!'),1.8);return}save.boost=!save.boost;persist();applyMoney()}

/* ---- 매일 보상: 출석 7일 · 미션 3개 · 광고 상자 ---- */
function canCheckin(){return save.checkin.last!==today()}
function rewardBadge(){dailyInit();return canCheckin()||MISSIONS.some((m,i)=>save.daily[m.k]>=m.n&&!save.daily.claimed[i])}
