let musicOn=true,vibOn=true,masterGain=null,musicGain=null,sfxGain=null,musicTimer=0,musicStep=0,musicNext=0,musicMode='',noiseBuf=null;
function audioInit(){if(audioCtx)return true;try{audioCtx=new (window.AudioContext||window.webkitAudioContext)();masterGain=audioCtx.createGain();masterGain.connect(audioCtx.destination);musicGain=audioCtx.createGain();musicGain.gain.value=0;musicGain.connect(masterGain);sfxGain=audioCtx.createGain();sfxGain.connect(masterGain);const n=audioCtx.sampleRate*.05;noiseBuf=audioCtx.createBuffer(1,n,audioCtx.sampleRate);const d=noiseBuf.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1;return true}catch(e){return false}}
function kick(){if(!audioInit())return;try{if(audioCtx.state==='suspended')audioCtx.resume()}catch(e){}wantMusic()}
function playNote(freq=400,type='sine',dur=.1){if(!sound||!audioInit())return;try{const o=audioCtx.createOscillator(),gn=audioCtx.createGain(),c=audioCtx.currentTime;o.type=type;o.frequency.setValueAtTime(freq,c);gn.gain.setValueAtTime(.09,c);gn.gain.exponentialRampToValueAtTime(.001,c+dur);o.connect(gn).connect(sfxGain);o.start(c);o.stop(c+dur+.02)}catch(e){}}
const SONG={play:{bpm:132,mel:[72,0,76,0,79,0,76,79,81,0,79,0,76,0,74,0,72,0,76,0,79,0,84,0,83,81,79,0,74,0,76,0],bass:[48,55,53,60,48,55,55,59],wave:'square',vol:.035},menu:{bpm:104,mel:[67,0,72,0,76,0,74,72,69,0,72,0,74,0,0,0,67,0,72,0,76,0,79,0,77,76,74,0,72,0,0,0],bass:[48,55,53,57,48,55,55,55],wave:'triangle',vol:.06}};
function mNote(f,c,dur,type,vol){const o=audioCtx.createOscillator(),gn=audioCtx.createGain();o.type=type;o.frequency.value=f;gn.gain.setValueAtTime(vol,c);gn.gain.exponentialRampToValueAtTime(.0008,c+dur);o.connect(gn).connect(musicGain);o.start(c);o.stop(c+dur+.02)}
function hat(c){const s=audioCtx.createBufferSource(),gn=audioCtx.createGain(),hp=audioCtx.createBiquadFilter();hp.type='highpass';hp.frequency.value=7000;s.buffer=noiseBuf;gn.gain.setValueAtTime(.025,c);gn.gain.exponentialRampToValueAtTime(.001,c+.04);s.connect(hp).connect(gn).connect(musicGain);s.start(c)}
const mf=m=>440*Math.pow(2,(m-69)/12);
function musicTick(){if(!audioCtx||!musicMode)return;const S=SONG[musicMode],step=60/S.bpm/2;while(musicNext<audioCtx.currentTime+.25){const i=musicStep%32,c=Math.max(musicNext,audioCtx.currentTime);const m=S.mel[i];if(m)mNote(mf(m),c,step*.9,S.wave,S.vol);if(i%2===0){const b=S.bass[(i>>2)%8];mNote(mf(b),c,step*1.6,'triangle',.07)}if(musicMode==='play'&&i%2===1)hat(c);musicStep++;musicNext+=step}}
function setMusic(mode){if(!audioCtx){musicMode='';return}const target=(musicOn&&mode)?mode:'';const ducked=state==='quiz'?.25:1;try{musicGain.gain.setTargetAtTime(target?ducked:0,audioCtx.currentTime,.15)}catch(e){}if(target===musicMode)return;musicMode=target;clearInterval(musicTimer);if(target){musicStep=0;musicNext=audioCtx.currentTime+.08;musicTimer=setInterval(musicTick,90);musicTick()}}
