const GOODV={ko:/(google|yuna|sunhi|injoon|hyunsu|seoyeon|jimin|natural|neural|online|premium|enhanced|향상|siri)/i,zh:/(google|tingting|ting-ting|xiaoxiao|yunxi|xiaoyi|yunyang|lili|natural|neural|online|premium|enhanced|siri)/i,en:/(google|samantha|aria|jenny|guy|ava|natural|neural|online|premium|enhanced|siri)/i};
const NOVELTY=/(eddy|flo\b|grandma|grandpa|reed|rocko|sandy|shelley|albert|bad news|bahh|bells|boing|bubbles|cellos|good news|jester|organ|superstar|trinoids|whisper|wobble|zarvox|fred|junior|kathy|ralph|compact|eloquence|espeak|heami|할머니|할아버지)/i;
function pickVoice(lang){const want=LOCALE[lang].toLowerCase();let best=null,bs=-99;for(const v of VOICES){const vl=(v.lang||'').toLowerCase().replace('_','-');if(!vl.startsWith(lang))continue;let sc=0;if(vl===want)sc+=3;if(lang==='zh'&&/(hk|tw|yue|mo)/.test(vl))sc-=5;if(GOODV[lang].test(v.name))sc+=4;if(NOVELTY.test(v.name))sc-=12;if(v.localService)sc+=1;if(v.default)sc+=1;if(sc>bs){bs=sc;best=v}}return best}
const RATE={ko:[1,.78],zh:[.88,.68],en:[.92,.72]};
function noVoiceMsg(lang){const n={ko:['한국어','韩语','Korean'],zh:['중국어','中文','Chinese'],en:['영어','英语','English']}[lang];return L3('이 기기에 '+n[0]+' 음성이 없어요. 기기 설정에서 음성을 내려받으면 들을 수 있어요.','此设备没有'+n[1]+'语音，可在系统设置中下载语音。','No '+n[2]+' voice on this device. You can download one in system settings.')}
function say(text,lang,slow=false){if(!voiceActive)return;if(!hasSpeech){voiceHint(L3('이 기기에서는 음성 재생을 지원하지 않아요.','此设备不支持语音播放','Speech playback is unavailable on this device.'));return}
 try{stopSpeech();if(!VOICES.length)loadVoices();const v=pickVoice(lang);if(VOICES.length&&!v){voiceHint(noVoiceMsg(lang));return}const u=new SpeechSynthesisUtterance(text);u.lang=v?v.lang.replace('_','-'):LOCALE[lang];if(v)u.voice=v;u.rate=RATE[lang][slow?1:0];u.pitch=1;u.volume=1;u.onerror=ev=>{if(ev&&ev.error==='interrupted'||ev&&ev.error==='canceled')return;voiceHint(L3('음성 재생이 어려워요. 글자로 학습할 수 있어요.','语音无法播放，请直接阅读文字','Audio unavailable; read the text instead.'))};setTimeout(()=>{try{window.speechSynthesis.speak(u)}catch(e){}},40)}catch(e){voiceHint(L3('음성을 재생할 수 없어요.','语音不可用','Audio unavailable'))}}
function renderVoiceInfo(){const el=document.getElementById('voiceInfo');if(!el||typeof settings==='undefined')return;if(!hasSpeech){el.textContent=L3('이 기기는 발음 듣기를 지원하지 않아요.','此设备不支持语音。','This device has no speech support.');return}const nm={zh:'中文',ko:'한국어',en:'English'};el.innerHTML=['zh','ko','en'].map(l=>{const v=pickVoice(l);return nm[l]+': '+(v?v.name.replace(/[<>&]/g,''):(VOICES.length?'❌ '+L3('없음','无','none'):L3('기기 기본 음성','系统默认语音','device default')))}).join('<br>')}

