function loadImg(key,src,done,tries=0){const img=new Image();img.decoding='async';img.onload=()=>{IMGS[key]=img;done(true)};img.onerror=()=>{if(tries<8)setTimeout(()=>loadImg(key,src,done,tries+1),400*(tries+1));else{IMG_FAIL.push(key);done(false)}};img.src=src+(tries?('&r='+tries):'')}
function startLoading(){const jobs=[];ASSET_PATHS.avatars.forEach((s,i)=>jobs.push(['hero'+i,s]));ASSET_PATHS.busts.forEach((s,i)=>jobs.push(['bust'+i,s]));Object.entries(ASSET_PATHS.enemies).forEach(([k,s])=>jobs.push([k,s]));let n=0,finished=false;const t0=Date.now();const finish=()=>{if(finished)return;finished=true;clearInterval(slow);$('loadBar').style.width='100%';setTimeout(()=>{if(state==='menu'||state==='loading'){state='menu';menu()}if(IMG_FAIL.length){track('load_fail',{n:IMG_FAIL.length});notify(L3('그림 일부를 못 받았어요. 새로고침해 보세요','部分图片加载失败，请刷新','Some images failed. Try refreshing'),3)}},250)};
 const step=()=>{n++;$('loadBar').style.width=Math.round(n/jobs.length*100)+'%';tr('loadText',Math.round(n/jobs.length*100)+'%');if(n>=jobs.length)finish()};
 const slow=setInterval(()=>{const s=(Date.now()-t0)/1000;if(s>6&&!finished)tr('loadText',L3('인터넷이 느려 시간이 걸리고 있어요…','网络较慢，正在加载…','Slow connection, still loading…'));if(s>25)finish()},1000);
 jobs.forEach(([k,s])=>loadImg(k,s,step));track('app_open',{plat:PLAT,lang:settings.ui})}

